        ok(v[0] == "Summit Freightways Inc" and v[1] == "T-999" and v[2] == "VNL 860" and "Summit Freightways Inc" in v[3] and "VNL 860" in v[3] and "T-999" in v[3], f"…and they save and show ({v[:3]} · {v[3][:160]})")
        await pg.screenshot(path=os.path.join(OUT, "a1_tech_card.png"))
        await pg.keyboard.press("Control+z"); await pg.wait_for_timeout(400)
