        ok(has and float(qv) == 7.5, f"Technician clock card: Quoted changes in place ({has}, {qv})")
        # 3 · the Parts tab's actions — the RO page's own, mounted on the Technician page (Parsec 14.3)
        await pg.evaluate("(()=>{ const R=" + "document.querySelector('[data-pg=tech] .jc-host').shadowRoot" + "; const t=[...R.querySelectorAll('.px-tabs [role=tab]')].find(b=>/Parts/.test(b.textContent)); if(t) t.click(); })()"); await pg.wait_for_timeout(400)
