        await pg.evaluate("(()=>{ const b=[..." + SRJ + ".querySelectorAll('.rop-tacts button')].find(b=>/Add part/.test(b.title||b.getAttribute('aria-label')||'')); if(b) b.click(); })()"); await pg.wait_for_timeout(300)
